'From Squeak6.0 of 8 June 2026 [latest update: #22156] on 27 July 2026 at 9:54:28 pm'!"Change Set:		Browser-mainPackageMenu-translatedDate:			27 July 2026Author:			Masashi UmezawaAdd translated to Browser-mainPackageMenu"!!Browser methodsFor: 'system category functions' stamp: 'mu 7/27/2026 21:36'!mainPackageMenu: aMenu	<packageMenu>		self selectedPackage ifNil: [		^ aMenu			add: '(No package found.)' translated action: #yourself;			yourself].		aMenu addList: #(			('browse package'							browsePackage)			#-			('extensions'				browsePackageExtensions)).		aMenu		add: ('extensions local to ''{1}''' translated format: {self selectedSystemCategory})		action: #browsePackageExtensionsLocalTo.		aMenu addList: #(			#-			('dependencies'				browsePackageDependencies)			('inverted dependencies'	browsePackageDependenciesInverted)).		^ aMenu! !